const canvas = new OffscreenCanvas(1, 1);
const $context = canvas.getContext("2d");
/**
 * @description 矩形内に含まれてない座標を返却
 *              Returns coordinates that are not included in the rectangle
 *
 * @param  {number[]} points
 * @param  {IPath} rectangle
 * @return {number[] | null}
 * @method
 * @protected
 */
export const execute = (points, rectangle) => {
    $context.beginPath();
    $context.moveTo(rectangle[0], rectangle[1]);
    for (let idx = 3; idx < rectangle.length; idx += 3) {
        if (rectangle[idx + 2]) {
            $context.quadraticCurveTo(rectangle[idx], rectangle[idx + 1], rectangle[idx + 3], rectangle[idx + 4]);
            idx += 3;
        }
        else {
            $context.lineTo(rectangle[idx], rectangle[idx + 1]);
        }
    }
    $context.closePath();
    for (let idx = 0; idx < points.length; idx += 2) {
        const x = points[idx];
        const y = points[idx + 1];
        if ($context.isPointInPath(x, y)) {
            continue;
        }
        return [x, y];
    }
    return null;
};
